  `guest_phone` text DEFAULT NULL,
  `staff_id` bigint(20) UNSIGNED DEFAULT NULL,
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `status` enum('pending','confirmed','checked_in','completed','cancelled','no_show') NOT NULL DEFAULT 'pending',
  `source` varchar(50) NOT NULL DEFAULT 'website',
  `total` decimal(12,2) NOT NULL,
  `discount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `tax` decimal(12,2) NOT NULL DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `cancellation_reason` text DEFAULT NULL,
  `reminded_at` timestamp NULL DEFAULT NULL,
  `calendar_event_id` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `active_slot_key` tinyint(4) GENERATED ALWAYS AS (case when `status` not in ('cancelled','no_show') and `deleted_at` is null then 1 else NULL end) STORED,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `confirmed_via` varchar(20) DEFAULT NULL,
  `confirmed_by` bigint(20) UNSIGNED DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

