CREATE TABLE `deals` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `subtitle` varchar(255) DEFAULT NULL,
  `category_tag` varchar(255) DEFAULT NULL,
  `slug` varchar(255) NOT NULL,
  `type` enum('percent','fixed','bundle') NOT NULL,
  `value` decimal(12,2) NOT NULL,
  `original_price` decimal(12,2) DEFAULT NULL,
  `deal_price` decimal(12,2) DEFAULT NULL,
  `included_services` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`included_services`)),
  `description` text DEFAULT NULL,
  `terms` text DEFAULT NULL,
  `image_path` varchar(255) DEFAULT NULL,
  `stock_image_url` varchar(2048) DEFAULT NULL,
  `code` varchar(50) DEFAULT NULL,
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `usage_limit` int(10) UNSIGNED DEFAULT NULL,
  `per_user_limit` int(10) UNSIGNED DEFAULT NULL,
  `min_amount` decimal(12,2) DEFAULT NULL,
  `is_stackable` tinyint(1) NOT NULL DEFAULT 0,
  `is_auto_apply` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_top_deal` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

