(41, NULL, 'Fatima Saleem', NULL, NULL, NULL, 5, NULL, 'I have been coming here for about one year And I always love her work I wish you all the best for future also ❤️❤️❤️', 'approved', 'google', NULL, '2026-10-20 09:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(42, NULL, 'Irma Umar', NULL, NULL, NULL, 5, NULL, 'I have been going to Look Smart Salon for almost 10 years, and my experience has always been absolutely amazing! ❤️ She is extremely cooperative, positive, professional, and genuinely dedicated to providing the best services to her clients.\n\nWhat I love most is the attention to detail. She and her staff take proper time with every client, listen carefully, and discuss each and every detail before providing the service. Her makeup and hairstyling are simply 200% perfect! Every time, I leave the salon completely satisfied and happy.\n\nHer staff is also highly professional, well-mannered, and attentive. The quality of service is truly exceptional, especially considering the very reasonable and affordable charges.\n\nIn my opinion, Look Smart Salon is one of the best service providers in Lahore at such reasonable prices. I would highly recommend it to everyone looking for professional, reliable, and excellent beauty services.\n\n2000% HIGHLY RECOMMENDED! ❤️✨', 'approved', 'google', NULL, '2026-10-18 09:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(43, NULL, 'Shakeela Shahzad', NULL, NULL, NULL, 5, NULL, 'Had an amazing experience at the salon today. The staff was super friendly and professional, taking their time to understand exactly what I wanted instead of rushing through. The place was spotless, well-maintained, and had a great relaxing vibe. Absolutely loved the final results and will definitely be coming back. Highly recommended to anyone looking for quality service.', 'approved', 'google', NULL, '2026-10-17 09:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(44, NULL, 'Sana Ch.', NULL, NULL, NULL, 5, NULL, 'Madam owner is very humble and good in dealing. Services are outstanding. A good saloon in society.', 'approved', 'google', NULL, '2026-10-16 09:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(45, NULL, 'Zainab Arslan', NULL, NULL, NULL, 5, NULL, 'Bohat acha experience hai. Services bohat achi hain. Make up bohat acha krti hain. Highly recommended for best services', 'approved', 'google', NULL, '2026-06-20 09:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(46, NULL, 'Hina Ali', NULL, NULL, NULL, 5, NULL, 'Very good service and owner is very nice lady my experience is 12 years it was very good', 'approved', 'google', NULL, '2026-02-20 10:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(47, NULL, 'Shazia patras', NULL, NULL, NULL, 5, NULL, 'Absolutely loved my experience here! The staff treated me so well and the results were even better than I expected. The salon is clean, relaxing, and very professional. I walked out feeling amazing. Truly the best — highly recommended! ⭐️🤩🤩', 'approved', 'google', NULL, '2026-01-21 10:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(48, NULL, 'Nouman_ SanDhu', NULL, NULL, NULL, 5, NULL, 'Absolutely loved my haircut and hair color. Great service and outstanding results. Highly recommended!', 'approved', 'google', NULL, '2026-01-16 10:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(49, NULL, 'Muqdas Abishay', NULL, NULL, NULL, 5, NULL, 'Amazing service truly satisfied the results\nVery professional and friendly staff loved the experience\nGreat attention to detail and exactly what I asked for Thank you', 'approved', 'google', NULL, '2025-11-17 10:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(50, NULL, 'Mrs Gsvali', NULL, NULL, NULL, 5, NULL, 'Best salon in Central park I was vist last 5 year regularly', 'approved', 'google', NULL, '2025-11-12 10:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(51, NULL, 'uzma zaheen', NULL, NULL, NULL, 5, NULL, 'Highly recommended, A true professional with magic in her hands 💇‍♀️', 'approved', 'google', NULL, '2025-11-02 10:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL),
(52, NULL, 'mahrukh zahid', NULL, NULL, NULL, 5, NULL, 'I am their regular client. Excellent skin care , hair care and polisher services. Must visit for high quality services.', 'approved', 'google', NULL, '2024-11-17 10:08:00', 0, '2026-11-17 10:08:00', '2026-11-17 10:08:00', NULL);

