(1, 1, 'HAIR-XTENSO-LOREAL', 'L\'Oréal X-Tenso Smooth', 'loreal-x-tenso-smooth', NULL, 'An advanced protein smoothing therapy that relaxes the hair\'s internal bonds for a sleek, manageable finish without flattening its natural movement.', 180, 20, 12000.00, 1, 1, 1, 'L\'Oréal X-Tenso Smooth | Looks Smart Beauty Salon, Lahore', 'An advanced protein smoothing therapy that relaxes the hair\'s internal bonds for a sleek, manageable finish without flattening its natural movement.', NULL, '2026-11-17 10:07:57', '2026-11-17 10:07:57', NULL),
(2, 1, 'HAIR-EXTENSO-SIG', 'Signature Extenso Straightening', 'signature-extenso-straightening', NULL, 'Our premium straightening service, formulated for a long-lasting poker-straight result that holds its shape through months of regular washing.', 180, 20, 19500.00, 1, 1, 2, 'Signature Extenso Straightening | Looks Smart Beauty Salon, Lahore', 'Our premium straightening service, formulated for a long-lasting poker-straight result that holds its shape through months of regular washing.', NULL, '2026-11-17 10:07:57', '2026-11-17 10:07:57', NULL),
(3, 1, 'HAIR-REBOND-PERM', 'Permanent Rebonding', 'permanent-rebonding', NULL, 'A structural transformation that permanently re-forms the hair\'s bonds for an ultra-sleek, glass-smooth result on even the most resistant textures.', 240, 30, 23250.00, 0, 1, 3, 'Permanent Rebonding | Looks Smart Beauty Salon, Lahore', 'A structural transformation that permanently re-forms the hair\'s bonds for an ultra-sleek, glass-smooth result on even the most resistant textures.', NULL, '2026-11-17 10:07:57', '2026-11-17 10:07:57', NULL),
(4, 1, 'HAIR-EXTENSO-KERATIN', 'Extenso + Keratin Dual Therapy', 'extenso-keratin-dual-therapy', NULL, 'Two treatments in one sitting: straightening for smoothness, followed by an intensive keratin repair layer for mirror-like shine and reinforced strands.', 240, 30, 27000.00, 1, 1, 4, 'Extenso + Keratin Dual Therapy | Looks Smart Beauty Salon, Lahore', 'Two treatments in one sitting: straightening for smoothness, followed by an intensive keratin repair layer for mirror-like shine and reinforced strands.', NULL, '2026-11-17 10:07:57', '2026-11-17 10:07:57', NULL),
(5, 1, 'HAIR-BOTOX', 'Hair Botox Restorative Treatment', 'hair-botox-restorative-treatment', NULL, 'A deep-conditioning fibre treatment that floods dehydrated strands with moisture and reseals a roughened cuticle, softening frizz without altering texture.', 90, 15, 12000.00, 0, 1, 5, 'Hair Botox Restorative Treatment | Looks Smart Beauty Salon, Lahore', 'A deep-conditioning fibre treatment that floods dehydrated strands with moisture and reseals a roughened cuticle, softening frizz without altering texture.', NULL, '2026-11-17 10:07:57', '2026-11-17 10:07:57', NULL),
(6, 1, 'HAIR-PERM-GLAM', 'Glamour Hair Perming', 'glamour-hair-perming', NULL, 'Permanent waves set to your preferred curl size, building lasting volume and definition that needs little more than a scrunch to revive each morning.', 120, 15, 6750.00, 0, 1, 6, 'Glamour Hair Perming | Looks Smart Beauty Salon, Lahore', 'Permanent waves set to your preferred curl size, building lasting volume and definition that needs little more than a scrunch to revive each morning.', NULL, '2026-11-17 10:07:57', '2026-11-17 10:07:57', NULL),
(7, 1, 'HAIR-COLOR-SHOULDER', 'Full Hair Color (Shoulder Length)', 'full-hair-color-shoulder-length', NULL, 'Complete root-to-tip colour for shoulder-length hair, giving even, saturated coverage in the shade you choose during consultation.', 90, 15, 4500.00, 0, 1, 7, 'Full Hair Color (Shoulder Length) | Looks Smart Beauty Salon, Lahore', 'Complete root-to-tip colour for shoulder-length hair, giving even, saturated coverage in the shade you choose during consultation.', NULL, '2026-11-17 10:07:57', '2026-11-17 10:07:57', NULL),
