CREATE TABLE `visitor_sessions` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `session_id` varchar(64) NOT NULL,
  `first_seen_at` timestamp NULL DEFAULT NULL,
  `last_seen_at` timestamp NULL DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `device_type` varchar(10) DEFAULT NULL,
  `browser` varchar(30) DEFAULT NULL,
  `os` varchar(30) DEFAULT NULL,
  `screen` varchar(15) DEFAULT NULL,
  `language` varchar(12) DEFAULT NULL,
  `timezone` varchar(40) DEFAULT NULL,
  `source` varchar(60) DEFAULT NULL,
  `landing_path` varchar(255) DEFAULT NULL,
  `country` varchar(2) DEFAULT NULL,
  `region` varchar(80) DEFAULT NULL,
  `city` varchar(80) DEFAULT NULL,
  `is_bot` tinyint(1) NOT NULL DEFAULT 0,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `name` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `cart` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`cart`)),
  `cart_total` decimal(12,2) DEFAULT NULL,
  `cart_updated_at` timestamp NULL DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'new',
  `note` text DEFAULT NULL,
  `pages_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

